## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;

  localparam int           CLK_PERIOD = 8;
  localparam logic [15:0]  PRESCALE   = 16'd5;
  localparam int           BIT_CLKS   = 40;   // prescale(5) * 8

  logic        clk             = 1'b0;
  logic        rst             = 1'b1;
  logic        rxd             = 1'b1;
  logic        m_axis_tready   = 1'b0;
  logic [7:0]  s_axis_tdata    = 8'h00;
  logic        s_axis_tvalid   = 1'b0;
  logic [15:0] prescale        = PRESCALE;

  wire         s_axis_tready;
  wire         txd;
  wire [7:0]   m_axis_tdata;
  wire         m_axis_tvalid;
  wire         tx_busy;
  wire         rx_busy;
  wire         rx_overrun_error;
  wire         rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  // Instantiate the top-level design with its default parameters (DATA_WIDTH=8).
  uart dut (
    .clk              (clk),
    .rst              (rst),
    .s_axis_tdata     (s_axis_tdata),
    .s_axis_tvalid    (s_axis_tvalid),
    .s_axis_tready    (s_axis_tready),
    .m_axis_tdata     (m_axis_tdata),
    .m_axis_tvalid    (m_axis_tvalid),
    .m_axis_tready    (m_axis_tready),
    .rxd              (rxd),
    .txd              (txd),
    .tx_busy          (tx_busy),
    .rx_busy          (rx_busy),
    .rx_overrun_error (rx_overrun_error),
    .rx_frame_error   (rx_frame_error),
    .prescale         (prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1; wait_clks(2);
    rst = 1'b0; wait_clks(2);
  endtask

  // Good 8N1 frame on rxd (LSB first), each bit held BIT_CLKS clocks.
  task automatic uart_send_good(input byte unsigned b);
    rxd = 1'b0;                 wait_clks(BIT_CLKS);   // start
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];              wait_clks(BIT_CLKS);   // data, LSB first
    end
    rxd = 1'b1;                 wait_clks(BIT_CLKS);   // stop = 1
  endtask

  // Bad 8N1 frame on rxd: stop bit = 0 -> frame_error, then return to mark.
  task automatic uart_send_bad(input byte unsigned b);
    rxd = 1'b0;                 wait_clks(BIT_CLKS);   // start
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];              wait_clks(BIT_CLKS);   // data, LSB first
    end
    rxd = 1'b0;                 wait_clks(BIT_CLKS);   // stop = 0 (frame error)
    rxd = 1'b1;                 wait_clks(BIT_CLKS);   // return to mark
  endtask

  initial begin
    do_reset();

    // m_axis_tready is held low the whole time: no handshake, so any
    // delivered word stays pending (m_axis_tvalid high, m_axis_tdata stable).

    // ---- Step 1: deliver 8'h3C; it stays held pending (tvalid high, tdata 3C,
    //              tready low, no handshake).
    uart_send_good(8'h3C);
    begin
      int c = 0;
      while (!(m_axis_tvalid && (m_axis_tdata == 8'h3C)) && c < 10000) begin
        @(negedge clk); c++;
      end
    end

    // ---- Step 2: while 8'h3C is still held, send a bad frame. Its bad stop bit
    //              pulses frame_error exactly while (tvalid=1, tdata=3C, tready=0),
    //              which arms the R26 state.
    uart_send_bad(8'h00);
    wait_clks(20);

    // ---- Step 3: send a good frame 8'hA5. It completes while 8'h3C is still
    //              pending, so m_axis_tdata changes 3C -> A5 with tvalid still
    //              high and overrun_error pulsed. R26 fires one clock later.
    uart_send_good(8'hA5);
    begin
      int c = 0;
      while (!(m_axis_tvalid && (m_axis_tdata == 8'hA5)) && c < 10000) begin
        @(negedge clk); c++;
      end
    end
    wait_clks(50);   // cover property samples one clock after the stop sample

    $display("PASS tb R26");
    $finish;
  end

  // Safety watchdog (must not fire when the sequence completes normally).
  initial begin
    #200us;
    $fatal(1, "timeout");
  end

endmodule
